        "question": "Czym różnią się skanery BE470 i SE4710 w Bluebird S10?",
        "answer": "W S10 występują dwa moduły: silnik Bluebird BE470 albo imager Zebra SE4710. Oba czytają kody 1D i 2D. Wersja 4G LTE ma SE4710."
